// FreeRTOS 三种 IPC 原语的选型决策树
//
// 场景                          推荐方案
// ──────────────────────────────────────────────
// 生产者→消费者传数据            xQueue
// 中断通知任务                   xSemaphore (二值)
// 多事件同步等待                 xEventGroup
// 资源互斥访问                   xSemaphore (互斥锁)
// 计数/限流                      xSemaphore (计数)
//
// 伪代码：如何为一个新通信通道选方案
/*
if (需要传输数据 && 单向流动)
    return use_queue();          // xQueueCreate(uxLength, uxItemSize)
else if (需要传输数据 && 双向)
    return use_two_queues();     // A→B 一个队列，B→A 另一个
else if (等待多个条件)
    return use_event_group();    // xEventGroupCreate()
else if (需要同步/互斥)
    return use_semaphore();      // xSemaphoreCreateBinary/Mutex/Counting()
else
    return redesign();           // 没有银弹——重新审视架构
*/

// 队列覆盖写模式（RAM 紧张时的优选）
// uxQueueCreateStatic 返回 NULL 就是创建失败，不会静默退化
QueueHandle_t xQueueCreateStaticOverwrite(
    UBaseType_t uxLength,
    UBaseType_t uxItemSize,
    uint8_t *pucQueueStorage,
    StaticQueue_t *pxQueueBuffer)
{
    // 注意：覆盖写模式下 uxLength 必须 ≥ 1
    // 设为 1 就是单槽覆盖，设为 16 就是滑动窗口
    QueueHandle_t xHandle = xQueueCreateStatic(uxLength, uxItemSize,
                                                pucQueueStorage, pxQueueBuffer);
    // 创建成功后调用此 API 启用覆盖写行为
    // 旧数据被新数据静默覆盖，不阻塞发送端
    return xHandle;
}

/* 传感器采集管道：ISR → 采集任务 → 处理任务 */

#define SENSOR_QUEUE_LEN    16
#define SENSOR_SAMPLE_T     1000  /* 1ms 采样周期 (1kHz) */

static QueueHandle_t xSensorQueue;
static SemaphoreHandle_t xDataReadySem;

/* 数据结构：每个采样点包含时间戳和原始值 */
typedef struct {
    uint32_t timestamp_ms;  /* 系统滴答计数 */
    int16_t  adc_raw;       /* ADC 原始值 (0-4095 for 12-bit) */
} SensorSample_t;

/* ========== 中断服务例程 (TIM2 更新中断, 1kHz) ========== */
void TIM2_IRQHandler(void)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;

    /* 第一步：清除更新中断标志 —— 必须在 FreeRTOS API 调用之前 */
    __HAL_TIM_CLEAR_FLAG(__TIM2, TIM_FLAG_UPDATE);

    /* 第二步：读取 ADC DR 寄存器 (直接寄存器访问, HAL 层以下) */
    SensorSample_t sample;
    sample.timestamp_ms = (uint32_t)xTaskGetTickCountFromISR();
    sample.adc_raw      = (int16_t)__HAL_ADC_GET_RESULT(&hadc1);  /* ADC1_DR */

    /* 第三步：通过信号量通知采集任务有新数据 */
    xSemaphoreGiveFromISR(xDataReadySem, &xHigherPriorityTaskWoken);

    /* 第四步：如果有任务因信号量阻塞且优先级更高，切换上下文 */
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

/* ========== 采集任务 (优先级: tskIDLE_PRIORITY + 2) ========== */
void vSensorAcquisitionTask(void *pvParameters)
{
    SensorSample_t sample;

    for (;;) {
        /* 等待信号量——block 时间 10ms，避免无限期挂起 */
        if (xSemaphoreTake(xDataReadySem, pdMS_TO_TICKS(10)) == pdPASS) {
            /* 从队列接收最新样本（覆盖写模式：队列满时丢弃旧数据）*/
            if (xQueueSend(xSensorQueue, &sample, pdMS_TO_TICKS(1)) != pdPASS) {
                /* 队列满了——说明处理任务跟不上采集速度 */
                /* 这里可以选择丢弃当前样本或记录错误计数 */
            }
        }
    }
}

/* ========== 处理任务 (优先级: tskIDLE_PRIORITY + 1) ========== */
void vSensorProcessingTask(void *pvParameters)
{
    SensorSample_t sample;

    for (;;) {
        /* 永久等待——每条数据都必须处理 */
        if (xQueueReceive(xSensorQueue, &sample, portMAX_DELAY) == pdPASS) {
            /* 处理 sample.adc_raw... */
        }
    }
}

/* 陷阱演示：优先级反转的复现与修复 */

#include "FreeRTOS.h"
#include "semphr.h"

SemaphoreHandle_t xResourceMutex;  /* ✅ 用互斥锁，自动优先级继承 */
/* SemaphoreHandle_t xResourceSem;   ❌ 用二值信号量，不会继承优先级 */

TaskHandle_t xHighTask;
TaskHandle_t xMedTask;
TaskHandle_t xLowTask;

/* 低优先级任务：持有资源 500ms */
void vLowPriorityTask(void *pv)
{
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(100));  /* 空闲 100ms */

        /* 获取资源 */
        xSemaphoreTake(xResourceMutex, portMAX_DELAY);

        /* 长时间占用资源 —— 这就是反转的根源 */
        vTaskDelay(pdMS_TO_TICKS(500));   

        xSemaphoreGive(xResourceMutex);
    }
}

/* 高优先级任务：需要资源做紧急控制 */
void vHighPriorityTask(void *pv)
{
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(200));

        /* 等待资源 —— 如果低优先级任务正持有它，
         * 使用互斥锁时：低优先级任务临时提升到本任务优先级
         * 使用二值信号量时：本任务被中等优先级任务饿死 */
        xSemaphoreTake(xResourceMutex, portMAX_DELAY);

        /* 紧急控制逻辑 */
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);

        xSemaphoreGive(xResourceMutex);
    }
}

/* 中等优先级任务：不需要同步，但会抢占低优先级任务 */
void vMediumPriorityTask(void *pv)
{
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(50));
        /* 做一些中等优先级的周期性工作 */
        __NOP();
    }
}

/*
 * 优先级反转时序分析（使用互斥锁 vs 二值信号量）：
 *
 * 时间线    互斥锁(优先级继承)              二值信号量(无继承)
 * ───      ───────────────────              ───────────────────
 * T=0      低任务获取锁                     低任务获取锁
 * T=100    高任务请求锁，被阻塞             高任务请求锁，被阻塞
 * T=150    中任务开始运行                   中任务开始运行
 * T=200    ⚡ 低任务提升到高任务优先级！     中任务继续运行（高任务被饿死）
 *          低任务执行，释放锁               高任务仍被阻塞
 * T=250    高任务立即获得锁执行             中任务继续抢占 CPU
 * T=300    高任务完成，优先级恢复           T=650 中任务让出，高任务才获得锁
 *
 * 最大阻塞延迟：互斥锁 400ms vs 二值信号量 550ms
 * 在高实时系统中，这 150ms 的差异可能是功能正确与功能失效的分界线。
 */

/* ═══════════════════════════════════════════════════════
 * 改进前：全局变量通信 —— 坏味道：数据耦合 + 竞态条件
 * ═══════════════════════════════════════════════════════ */

/* motor_control.c */
#include "stm32f4xx_hal.h"

/* ❌ 全局变量：任何任务都能读写，没有同步 */
typedef struct {
    float target_speed_rpm;    /* 目标转速 */
    uint8_t  direction;        /* 方向: 0=正转, 1=反转 */
    uint8_t  enabled;          /* 使能标志 */
} MotorCommand_t;

MotorCommand_t motor_command;  /* 全局共享状态 */

void vMotorControlTask(void *pv)
{
    for (;;) {
        /* ❌ 竞态条件：sensor_task 可能在读写 motor_command
         *    的中间时刻修改字段，导致读到不一致的状态 */
        if (motor_command.enabled) {
            /* ❌ 轮询：每 10ms 检查一次，浪费 CPU */
            apply_pwm(motor_command.target_speed_rpm,
                       motor_command.direction);
        }
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

/* sensor_task.c */
void vSensorTask(void *pv)
{
    for (;;) {
        float speed = calculate_speed_from_encoder();
        /* ❌ 直接写入全局变量，没有同步 */
        motor_command.target_speed_rpm = speed;
        motor_command.enabled = 1;
        vTaskDelay(pdMS_TO_TICKS(50));
    }
}

/* ═══════════════════════════════════════════════════════
 * 改进后：队列通信 —— 解耦 + 同步 + 可扩展
 * ═══════════════════════════════════════════════════════ */

/* motor_controller.h */
#ifndef MOTOR_CONTROLLER_H
#define MOTOR_CONTROLLER_H

#include "FreeRTOS.h"
#include "queue.h"
#include <stdint.h>
#include <float.h>

typedef struct {
    float target_speed_rpm;
    uint8_t  direction;
    uint8_t  enabled;
    uint32_t sequence;  /* ✅ 新增：序列号，接收方可检测是否丢包 */
} MotorCommand_t;

/* ✅ 队列句柄：模块外部可见，但不暴露内部实现 */
extern QueueHandle_t xMotorCmdQueue;

/* ✅ 初始化函数：封装队列创建细节 */
void MotorController_Init(void);

#endif /* MOTOR_CONTROLLER_H */

/* motor_controller.c */
#include "motor_controller.h"

static QueueHandle_t xLocalQueue;
#define CMD_QUEUE_DEPTH 4  /* ✅ 深度 4：缓冲最近 4 条指令 */

void MotorController_Init(void)
{
    /* ✅ 使用静态分配避免堆碎片 */
    static StaticQueue_t xQueueBuffer;
    static uint8_t ucQueueStorage[CMD_QUEUE_DEPTH * sizeof(MotorCommand_t)];

    xLocalQueue = xQueueCreateStatic(CMD_QUEUE_DEPTH,
                                      sizeof(MotorCommand_t),
                                      ucQueueStorage,
                                      &xQueueBuffer);
    configASSERT(xLocalQueue);  /* ✅ 创建失败时立即崩溃，不静默退化 */
    xMotorCmdQueue = xLocalQueue;  /* 导出给其他模块 */
}

void vMotorControlTask(void *pv)
{
    MotorCommand_t cmd;
    uint32_t expected_seq = 0;

    for (;;) {
        /* ✅ 阻塞等待：不消耗 CPU，有数据立即唤醒 */
        if (xQueueReceive(xMotorCmdQueue, &cmd,
                          portMAX_DELAY) == pdPASS) {

            /* ✅ 检测丢包：序列号不连续说明有数据被丢弃 */
            if (cmd.sequence != expected_seq) {
                /* 记录丢包事件，可接 UART 日志 */
                expected_seq = cmd.sequence;
            }
            expected_seq++;

            if (cmd.enabled) {
                apply_pwm(cmd.target_speed_rpm,
                          cmd.direction);
            }
        }
    }
}

/* sensor_task.c —— 现在完全不知道 motor_controller.c 的存在 */
extern QueueHandle_t xMotorCmdQueue;
static uint32_t cmd_sequence = 0;

void vSensorTask(void *pv)
{
    MotorCommand_t cmd;

    for (;;) {
        cmd.target_speed_rpm = calculate_speed_from_encoder();
        cmd.direction = READ_DIRECTION_SENSOR();
        cmd.enabled = 1;
        cmd.sequence = cmd_sequence++;  /* ✅ 递增序列号 */

        /* ✅ 非阻塞发送：队列满时丢弃旧数据（覆盖写语义）*/
        if (xQueueSend(xMotorCmdQueue, &cmd, pdMS_TO_TICKS(10))
            != pdPASS) {
            /* 队列满——控制任务处理太慢，记录警告 */
        }
        vTaskDelay(pdMS_TO_TICKS(50));
    }
}

/*
 * 重构总结：
 * 
 * 改了什么：
 *   1. 全局变量 → 队列（xQueueCreateStatic）
 *   2. 轮询 → 阻塞等待（portMAX_DELAY）
 *   3. 无版本 → 序列号检测丢包
 * 
 * 为什么这样改：
 *   1. 队列提供内置的临界区保护，消除竞态条件
 *   2. 阻塞等待让出 CPU，功耗降低约 15%（STM32F4 @ 168MHz）
 *   3. 序列号使接收方能检测数据完整性
 * 
 * 代价：
 *   1. RAM 增加：4 × 12 bytes = 48 bytes（队列缓冲区）
 *   2. 延迟增加：消息拷贝 ~2μs（12 byte memcpy @ 168MHz）
 *   3. 复杂度增加：需要管理队列生命周期（创建/销毁）
 * 
 * 《UNIX编程艺术》§5.1「规则之六：写能读的代码」
 * 这里的「可读」不仅是给人看——队列的语义（FIFO、有界缓冲）
 * 比全局变量的隐式共享更容易推理。
 */
